function previewUnsafe(){const e=current();$('preview').textContent=e?e.translation||e.source:'';const canvas=$('previewCanvas');if(!e){canvas.width=0;canvas.height=0;$('bytes').textContent='';$('previewPageLabel').textContent='';$('previewPagePrev').disabled=true;$('previewPageNext').disabled=true;return;}const pages=(e.translation||e.source).split(/\{(?:PARA|SCROLL)\}/g);previewPage=Math.min(previewPage,Math.max(0,pages.length-1));$('previewPageLabel').textContent=(previewPage+1)+' / '+pages.length;$('previewPagePrev').disabled=previewPage===0;$('previewPageNext').disabled=previewPage===pages.length-1;const visual=pages[previewPage].replace(/\{(?:PARA|SCROLL)\}/g,'\n').replace(/\{VAR:01\}/g,'ผู้เล่น').replace(/\{(?:VAR|DYNAMIC):[0-9a-f]{2}\}/gi,'…').replace(/\{CTRL:[^}]+\}/g,'');PixelFont.draw(canvas,visual,{scale:Number($('fontScale').value),width:240,...pixelColors()});if($('nativePreview').checked&&rom){try{const nativeText=RomCore.layoutEntry(e,pages[previewPage],rom);TranslationQuality.draw(canvas,nativeText,rom,Number($('fontScale').value));}catch{}}canvas.style.width=canvas.width+'px';try{const info=RomCore.measure(e.translation),limit=e.storage==='inline'?e.capacity-1:e.budget;$('bytes').textContent=`ประมาณ ${info.bytes} ไบต์ · ${e.storage==='inline'?'ช่องชื่อ '+limit+' ไบต์':'ย้ายข้อความได้'}${info.thai?' · ฟอนต์ไทย GBA':''}`;const checked=TranslationQuality.entry(e,e.translation,rom,project.glossary);$('bytes').textContent+=` · ${checked.metrics?.width||0}/${checked.spec.width} px · ${checked.metrics?.lines||0}/${checked.spec.scroll?'เลื่อนหน้า':checked.spec.lines} บรรทัด`+(checked.issues.length?' · '+checked.issues.map(x=>x.message).join(' · '):'');$('bytes').className=checked.issues.some(x=>x.severity==='error')?'over':'';}catch(err){$('bytes').textContent=err.message;$('bytes').className='over';}}

