function select(i){selected=i;previewPage=0;render();rememberWorkView();}
function move(n){if(!project)return;const rows=filtered();const pos=rows.findIndex(({i})=>i===selected);const next=rows[Math.max(0,Math.min(rows.length-1,pos+n))];if(next){pageIndex=Math.floor(Math.max(0,pos+n)/PAGE_SIZE);select(next.i);}}
for(const k of ['translation','speaker','literal','contextual'])$(k).oninput=()=>{const e=current();if(!e)return;TranslationHistory.apply(project,[{id:e.id,[k]:$(k).value}],'แก้ '+k,true);save();historyControls();if(k==='translation'){renderList();preview();renderFormatIndicator();}if(k==='speaker'){updateCategoryTabs();renderProgress();renderFormatIndicator();}};
function leaveUnrelatedWork(category){const task=TranslationTasks.active(project),ids=task?new Set(task.entryIds):null;if(task&&(category==='all'||project.entries.some(e=>TranslationProgress.matches(e,category)&&!ids.has(e.id)))){TranslationTasks.finish(project,task.id,'paused');save(true);window.WorkManager?.renderCurrent();toast('พักงานชุด '+task.name+' เพื่อแสดงหมวดเต็ม · กลับไปทำต่อได้จากโปรเจกต์');}}

for(const button of document.querySelectorAll('[data-family]'))button.onclick=()=>{leaveUnrelatedWork(button.dataset.family);$('categoryFilter').value=button.dataset.family;progressOnly=false;pageIndex=0;renderList();rememberWorkView();};
for(const k of ['search','searchField','categoryFilter','todo','context'])$(k).addEventListener(k==='search'?'input':'change',()=>{if(k==='categoryFilter')leaveUnrelatedWork($('categoryFilter').value);progressOnly=false;pageIndex=0;if(k==='categoryFilter'){const rows=filtered(false);if(rows.length&&!rows.some(row=>row.i===selected)){selected=rows[0].i;previewPage=0;}}renderList();if(k==='categoryFilter')renderEditor();rememberWorkView();});$('clearSearch').onclick=()=>{$('search').value='';progressOnly=false;pageIndex=0;renderList();rememberWorkView();};$('pagePrev').onclick=()=>{pageIndex=0;renderList();rememberWorkView();};$('pageNext').onclick=()=>{pageIndex++;renderList();rememberWorkView();};
