$('copySource').onclick=()=>copy(current()?.source||'');$('copyTranslation').onclick=()=>copy($('translation').value);for(const k of ['literal','contextual']){$(k==='literal'?'literalCopy':'contextCopy').onclick=()=>copy($(k).value);$(k==='literal'?'literalUse':'contextUse').onclick=()=>{if(!current())return;TranslationHistory.apply(project,[{id:current().id,translation:$(k).value}],'ใช้คำแปล AI');save();render();};}

function workFilter(){return {category:$('categoryFilter').value,search:$('search').value,searchField:$('searchField').value,untranslated:$('todo').checked};}
function rememberWorkView(persist=true){if(!project)return;project.viewState={...workFilter(),context:$('context').checked,position:current()?.id,page:pageIndex};const task=TranslationTasks.active(project);if(task){task.filter=workFilter();if(task.entryIds.includes(current()?.id))task.position=current().id;if(persist)task.updatedAt=Date.now();}if(persist)save();}
function restoreWorkView(){const task=TranslationTasks.active(project),view=task?{...task.filter,position:task.position||task.entryIds[0]}:project?.viewState;if(!view)return;$('categoryFilter').value=[...$('categoryFilter').options].some(o=>o.value===view.category)?view.category:'all';$('search').value=view.search||'';$('searchField').value=view.searchField||'all';$('todo').checked=!!view.untranslated;$('context').checked=!!view.context;progressOnly=false;selected=Math.max(0,project.entries.findIndex(e=>e.id===view.position));const rows=filtered(false),position=rows.findIndex(r=>r.i===selected);pageIndex=position>=0?Math.floor(position/PAGE_SIZE):Math.min(view.page||0,Math.max(0,Math.ceil(rows.length/PAGE_SIZE)-1));}
async function openWorkFile(p,{guard,requireRom=false}={}){if(guard&&!guard())return false;if(!valid(p))throw Error('ไฟล์งานไม่ถูกต้อง');if(p.font)FontPresets.validate(p.font);if(!project||p.romHash!==project.romHash){
 if(loading)throw Error('รอเปิด ROM ปัจจุบันให้เสร็จก่อน');
 const previous=project;let cached=await readSaved('rom-'+p.romHash).catch(()=>null);
 if(!guard&&!cached?.bytes&&typeof FontCloud!=='undefined'&&FontCloud.connected()&&window.RomCloud){const bytes=await RomCloud.forResume(p,{strict:requireRom});if(bytes)cached={bytes,title:p.title};}
 if(guard&&!guard())return false;if(project!==previous||loading)throw Error('โปรเจกต์เปลี่ยนระหว่างโหลด กรุณาเปิดงานอีกครั้ง');
 if(cached?.bytes&&(cached.bytes.byteLength>33554432||await RomCore.fingerprint(cached.bytes)!==p.romHash))throw Error('ROM ที่เก็บไว้ไม่ตรงกับโปรเจกต์ กรุณาเลือก ROM ต้นฉบับ');
 if(requireRom&&!cached?.bytes)throw Error('ยังไม่มี ROM บนคลาวด์ · เปิด ROM ที่เครื่องเดิม แล้วกดเก็บ ROM บนคลาวด์ให้ครบก่อน');
 if(previous)await writeSaved(previous);if(guard&&!guard())return false;if(project!==previous||loading)throw Error('โปรเจกต์เปลี่ยนระหว่างโหลด กรุณาเปิดงานอีกครั้ง');pendingProject=p;pendingProjectAuto=!!guard;render();
 if(!cached?.bytes){toast('โหลดคำแปลแล้ว แต่ยังไม่มี ROM ที่พร้อมใช้ในเครื่องหรือคลาวด์ · เลือก ROM ต้นฉบับของ '+(p.workspaceName||p.title));return;}
 const files=new DataTransfer();files.items.add(new File([cached.bytes],cached.title||p.title));$('romFile').files=files.files;await $('romFile').onchange();return project?.workspaceId===p.workspaceId;
 }const originals=new Map(project.entries.map(e=>[e.romOffset,e]));if(p.entries.some(e=>originals.get(e.romOffset)?.source!==e.source))throw Error('ข้อมูลในไฟล์งานไม่ตรงกับข้อความต้นฉบับ');TranslationTasks.hydrate({entries:project.entries,title:project.title},p);if(!guard&&erasedTranslations(project,p)&&!confirm('ฉบับที่จะเปิดมีคำแปลว่างแทนของเดิม '+erasedTranslations(project,p)+' รายการ คำแปลเดิมในงานนี้จะถูกแทนที่ ต้องการเปิดฉบับนี้หรือไม่?'))return false;if(guard&&erasedTranslations(project,p))throw Error('หยุดเปิดคลาวด์อัตโนมัติ เพราะจะทำให้คำแปลในเครื่องว่าง '+erasedTranslations(project,p)+' รายการ · งานในเครื่องยังอยู่');await writeSaved(project);if(guard&&!guard())return false;const importedFont=p.font?await FontPresets.importData(p.font,false,{activate:false,cloud:false}):null;if(guard&&!guard())return false;TranslationHistory.checkpoint(project,'ก่อนเปิดไฟล์งาน');if(p.workspaceFormat==='RomTranslate workspace v1')project.history=undefined;if(p.workspaceFormat==='RomTranslate workspace v1')for(const e of project.entries)for(const k of ['translation','speaker','literal','contextual','translationChoice'])e[k]='';if(importedFont)FontPresets.apply(importedFont,false);merge(p);project.font=FontPresets.data();project.genre=p.genre||project.genre;TranslationHistory.hydrate(project,p.history);restoreWorkView();save(true,true);render();toast('เปิดไฟล์งานแล้ว · คำแปล ฟอนต์ หมวด และงานค้างถูกคืนแล้ว');return true;}
async function attachWorkspaceRom(file,expectedHash){
 if(!file||file.size<192||file.size>33554432)throw Error('เลือก ROM ต้นฉบับ .gba ขนาดไม่เกิน 32 MB');
 const bytes=new Uint8Array(await file.arrayBuffer());RomCore.header(bytes);
 if(await RomCore.fingerprint(bytes)!==expectedHash)throw Error('ROM ไม่ตรงกับงานนี้ · เลือกต้นฉบับเวอร์ชันเดียวกัน ไม่ใช่ไฟล์เกมที่สร้างแปลแล้ว · คำแปลเดิมยังอยู่');
 await cacheResumeRom(expectedHash,bytes,file.name);
}
async function autoResumeWorkspace(p,guard,cloudBytes=null){
 if(!valid(p))throw Error('ไฟล์งานคลาวด์ไม่ถูกต้อง');if(p.font)FontPresets.validate(p.font);
 if(!guard()||loading||pendingProject)return false;
 if(project)return openWorkFile(p,{guard});
 const cached=cloudBytes?{bytes:cloudBytes,title:p.title}:await readSaved('rom-'+p.romHash).catch(()=>null);
 if(cached?.bytes&&(cached.bytes.byteLength>33554432||await RomCore.fingerprint(cached.bytes)!==p.romHash))throw Error('ROM ที่จำไว้ไม่ตรงกับไฟล์งาน กรุณาเลือก ROM ต้นฉบับใหม่');
 if(!guard()||project||loading||pendingProject)return false;
 pendingProject=p;pendingProjectAuto=true;render();
 if(!cached?.bytes){toast('ดึงโปรเจกต์ “'+(p.workspaceName||p.title)+'” แล้ว เลือก ROM ต้นฉบับเพื่อทำต่อ');return true;}
 const files=new DataTransfer();files.items.add(new File([cached.bytes],cached.title||p.title));$('romFile').files=files.files;await $('romFile').onchange();return project?.workspaceId===p.workspaceId&&project.cloudRevision===p.cloudRevision;
}
