$('buildRom').onclick=async()=>{if(!rom||!project||UiOperations.busy)return;$('buildRom').disabled=true;$('saveState').textContent='กำลังตรวจสอบและสร้าง ROM…';try{pendingBuild=await UiOperations.run('สร้างไฟล์เกม',(signal,onProgress)=>RomCore.patch(rom,project.entries,{glossary:project.glossary,font:FontPresets.data(),genre:project.genre||$("aiGenre").value,progressCategories:TranslationProgress.selection(project),signal,onProgress}),{cancellable:true});$('buildInfo').textContent=`พร้อมส่งออก ${project.title} · แก้ไข ${pendingBuild.count} ข้อความ · ใช้ฟอนต์ ${pendingBuild.thaiGlyphs||0}/${pendingBuild.glyphCapacity||0} กลุ่มอักษร`;$('buildDialog').showModal();$('saveState').textContent='สร้าง ROM สำเร็จ';}catch(e){pendingBuild=null;toast(e.message,e.name==='AbortError'?'info':'error');$('saveState').textContent=e.name==='AbortError'?'ยกเลิกสร้างไฟล์เกมแล้ว':'สร้างไฟล์ไม่สำเร็จ — ดูข้อความแจ้งเตือน';}finally{$('buildRom').disabled=false;}};$('downloadPatch').onclick=async()=>{if(!pendingBuild)return;const source=rom.slice(),target=pendingBuild.bytes,title=project.title;$('downloadPatch').disabled=true;try{const patch=await RomPatch.create(source,target,title);download(new Blob([patch],{type:'application/octet-stream'}),title.replace(/\.gba$/i,'')+'-translation.bps');toast('ดาวน์โหลดแพตช์ BPS แล้ว');}catch(e){toast(e.message,'error');}finally{$('downloadPatch').disabled=false;}};$('downloadRom').onclick=()=>{if(!pendingBuild)return;download(new Blob([pendingBuild.bytes],{type:'application/octet-stream'}),project.title.replace(/\.gba$/i,'')+'-test.gba');$('buildDialog').close();pendingBuild=null;};$('closeBuild').onclick=()=>{$('buildDialog').close();pendingBuild=null;};
