async function removeLocalWorkspace(id){const d=await db();try{await new Promise((resolve,reject)=>{const t=d.transaction('projects','readwrite'),store=t.objectStore('projects'),r=store.get('work-'+id);r.onsuccess=()=>{const saved=r.result;if(!saved)return;store.delete('work-'+id);const q=store.get(saved.romHash);q.onsuccess=()=>{if(q.result?.workspaceId===id)store.delete(saved.romHash);};};t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}finally{d.close();}if(project?.workspaceId===id){clearTimeout(saveTimer);saveGeneration++;project=null;rom=null;pendingBuild=null;try{localStorage.removeItem('romtranslate.resume.v1');}catch{}render();}}
async function storeCloudState(id,metadata){const p=project?.workspaceId===id?project:null;if(p)Object.assign(p,metadata);const d=await db();try{await new Promise((resolve,reject)=>{const t=d.transaction('projects','readwrite'),store=t.objectStore('projects'),r=store.get('work-'+id);r.onsuccess=()=>{const saved=r.result;if(!saved)return;Object.assign(saved,metadata);store.put(saved,'work-'+id);const original=store.get(saved.romHash);original.onsuccess=()=>{if(original.result?.workspaceId===id)store.put({...original.result,...metadata},saved.romHash);};};t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}finally{d.close();}}
