$("romFile").addEventListener("cancel",()=>{if(pendingTranslated&&!loading&&!$("originalDialog").open)$("originalDialog").showModal();});
(()=>{const handle=$('columnResize'),panel=$('translationView');let ratio=44,drag=null;try{const saved=Number(localStorage.getItem('romtranslate.columns'));if(saved>=25&&saved<=70)ratio=saved;}catch{}function apply(save=false){const w=panel.getBoundingClientRect().width;if(w>700)ratio=Math.max(25,Math.min(70,(w-300)/w*100,ratio));panel.style.setProperty('--left-width',ratio+'%');handle.setAttribute('aria-valuenow',String(Math.round(ratio)));handle.setAttribute('aria-valuemin','25');handle.setAttribute('aria-valuemax','70');if(save)try{localStorage.setItem('romtranslate.columns',String(ratio));}catch{}}handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();drag=e.pointerId;handle.setPointerCapture(e.pointerId);document.body.classList.add('column-dragging');};handle.onpointermove=e=>{if(drag!==e.pointerId)return;const r=panel.getBoundingClientRect();ratio=(e.clientX-r.left)/r.width*100;apply();};for(const type of ['pointerup','pointercancel','lostpointercapture'])handle.addEventListener(type,e=>{if(drag!==e.pointerId)return;drag=null;document.body.classList.remove('column-dragging');apply(true);});handle.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();e.stopPropagation();ratio=e.key==='Home'?25:e.key==='End'?70:ratio+(e.key==='ArrowRight'?2:-2);apply(true);}};window.addEventListener("resize",()=>apply());apply();})();

$('coverageButton').onclick=()=>{const counts=Object.entries(FAMILY_NAMES).map(([f,n])=>n+': '+project.entries.filter(e=>e.family===f).length.toLocaleString());$('coverageSummary').textContent=counts.join(' · ');$('coverageRows').replaceChildren();for(const e of project.entries.filter(e=>e.family==='unclassified').slice(0,100)){const p=document.createElement('p');p.textContent=e.offset+' · '+e.source;$('coverageRows').append(p);}$('coverageDialog').showModal();};$('coverageClose').onclick=()=>$('coverageDialog').close();$('coverageShow').onclick=()=>{$('categoryFilter').value='unclassified';$('search').value='';$('todo').checked=false;$('context').checked=false;progressOnly=false;pageIndex=0;renderList();$('coverageDialog').close();};

