function renderFormatIndicator(){const e=current(),has=e&&TranslationProgress.eligible(e)&&TranslationProgress.translated(e);if(!has){$('autoCheckState').className='';$('autoCheckState').textContent='ยังไม่มีคำแปลฉบับจริง';return;}const checked=TranslationQuality.entry(e,e.translation,rom,project.glossary),errors=checked.issues.filter(x=>x.severity==='error').length,warnings=checked.issues.filter(x=>x.severity==='warning').length;$('autoCheckState').textContent=errors?'รูปแบบต้องแก้ '+errors+' จุด':'ผ่านตรวจรูปแบบ'+(warnings?' · ควรตรวจ '+warnings+' จุด':'');$('autoCheckState').className=errors?'format-error':'format-pass';}
function goToEntry(id){const i=project.entries.findIndex(e=>e.id===id);if(i<0)return;const task=TranslationTasks.active(project);if(task&&!task.entryIds.includes(id))TranslationTasks.finish(project,task.id,'paused');RomTranslateViews.show('translation');selected=i;$('search').value='';$('categoryFilter').value=project.entries[i].family;$('todo').checked=false;$('context').checked=false;progressOnly=false;previewPage=0;pageIndex=Math.floor(Math.max(0,filtered(false).findIndex(r=>r.i===i))/PAGE_SIZE);render();$('translation').focus();$('entryList').querySelector('[data-entry-id="'+id+'"]')?.scrollIntoView({block:'nearest'});}
$('qualityNext').onclick=async()=>{if(!project||UiOperations.busy)return;try{const report=await runQualityAudit(),issues=report.rows.filter(r=>r.severity==='error'),rows=issues.length?issues:report.rows,ids=[...new Set(rows.map(r=>r.id))];if(!ids.length){toast('ไม่พบจุดที่ต้องแก้จากการตรวจรูปแบบ ยังควรตรวจความหมายและเกมจริง');return;}const currentId=current()?.id,position=ids.indexOf(currentId),id=ids[(position+1)%ids.length];goToEntry(id);toast(rows.find(r=>r.id===id).message);}catch(e){toast(e.message,e.name==='AbortError'?'info':'error');}};
