async function cacheResumeRom(hash,bytes,title){const d=await db();try{await new Promise((resolve,reject)=>{const t=d.transaction('projects','readwrite'),store=t.objectStore('projects'),r=store.get('rom-'+hash);r.onsuccess=()=>{if(!r.result)store.put({bytes:bytes.slice(),title},'rom-'+hash);};t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}finally{d.close();}}
async function restoreLastProject(){let marker;try{marker=JSON.parse(localStorage.getItem('romtranslate.resume.v1')||'null');}catch{return;}if(!marker||!/^([a-f0-9]{64})$/.test(marker.hash)||project||loading)return;try{const d=await db();let cached;try{cached=await new Promise((resolve,reject)=>{const r=d.transaction('projects').objectStore('projects').get('rom-'+marker.hash);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}finally{d.close();}if(!cached?.bytes||project||loading||pendingProject)return;if(cached.bytes.byteLength>33554432||await RomCore.fingerprint(cached.bytes)!==marker.hash)throw Error('ROM ที่จำไว้ไม่ตรงกับต้นฉบับ กรุณาเปิด ROM เดิมอีกครั้ง');if(project||loading||pendingProject)return;const files=new DataTransfer();files.items.add(new File([cached.bytes],cached.title||'game.gba'));$('romFile').files=files.files;await $('romFile').onchange();}catch(e){toast('เปิดงานล่าสุดอัตโนมัติไม่ได้: '+e.message);}}
function flushLocalWork(){if(!project)return;clearTimeout(saveTimer);const p=project;rememberWorkView(false);writeSaved(p).catch(()=>{});}
window.addEventListener('pagehide',flushLocalWork);document.addEventListener('visibilitychange',()=>{if(document.hidden)flushLocalWork();});const startupRestore=new Promise(resolve=>setTimeout(()=>restoreLastProject().finally(resolve),0));
